```ts
export function computeStreaks(completedDates: Iterable<string>): { current: number; longest: number } {
  const set = new Set(completedDates)
  const today = todayKey()
  let current = 0
  let cursor = set.has(today) ? today : addDays(today, -1)
  while (set.has(cursor)) { current++; cursor = addDays(cursor, -1) }
  let longest = 0
  const sorted = [...set].sort()
  let run = 0
  let prev: string | null = null
  for (const d of sorted) {
    run = prev && addDays(prev, 1) === d ? run + 1 : 1
    if (run > longest) longest = run
    prev = d
  }
  if (current > longest) longest = current // can't happen, but for safety
  return { current, longest }
}
```
Note: `addDays(prev,1) === d` — works with YYYY-MM-DD string comparison. Good, testable.

