@import "tailwindcss";

/* Dark Mode: Klassengesteuert (Dark Mode folgt dem System, ist aber manuell umschaltbar). */
@custom-variant dark (&:where(.dark, .dark *));

@theme {
  /* Typografie: systemeigene Schriften mit Charakter, kein Webfont (Offline-App). */
  --font-sans: 'SF Pro Display', 'Geist Sans', 'Helvetica Neue', 'Segoe UI', system-ui,
    -apple-system, sans-serif;
  --font-serif: 'Iowan Old Style', 'New York', Georgia, 'Times New Roman', serif;
  --font-mono: 'Geist Mono', 'SF Mono', ui-monospace, 'JetBrains Mono', Menlo, monospace;

  /* Warmes Monochrom +Spot-Pastelle (Light) */
  --color-canvas: #fbfaf8;
  --color-surface: #ffffff;
  --color-ink: #111111;
  --color-body: #2f3437;
  --color-muted: #787774;
  --color-faint: #a3a29d;
  --color-line: #eaeaea;
  --color-line-strong: #dcdcd7;

  /* Ein zurückhaltender Akzent (Terrakotta) für Stimmung & Hervorhebungen. */
  --color-clay: #a2491f;
  --color-clay-soft: #f7eae1;

  --radius-card: 12px;
}

/* Dunkle Gegenwerte: dieselben Token, umgedreht – alle Utilities folgen automatisch. */
.dark {
  --color-canvas: #151412;
