/* Ruhige Mikro-Animationen – nur transform/opacity, wie vom Design-Skill gefordert. */
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pop {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(0.86);
  }
