}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/** Datumshilfen – alles lokal, als Schlüssel im Format YYYY-MM-DD. */

export function toKey(date: Date): string {
  const y = date.getFullYear()
  const m = String(date.getMonth() + 1).padStart(2, '0')
  const d = String(date.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

export function fromKey(key: string): Date {
  const [y, m, d] = key.split('-').map(Number)
  return new Date(y, m - 1, d)
}

export function todayKey(): string {
  return toKey(new Date())
}

export function addDays(key: string, days: number): string {
  const d = fromKey(key)
  d.setDate(d.getDate() + days)
  return toKey(d)
}

/** Die letzten n Tage (ältester zuerst), endend am heutigen Tag. */
export function lastNDays(n: number, end = todayKey()): string[] {
  const out: string[] = []
  for (let i = n - 1; i >= 0; i--) out.push(addDays(end, -i))
  return out
}

const longDate = new Intl.DateTimeFormat('de-DE', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
})

const shortDate = new Intl.DateTimeFormat('de-DE', {
  day: 'numeric',
  month: 'short',
})

const monthOnly = new Intl.DateTimeFormat('de-DE', { month: 'long' })

const weekdayShort = new Intl.DateTimeFormat('de-DE', { weekday: 'short' })

export function formatLongDate(key: string): string {
  return longDate.format(fromKey(key))
}

export function formatShortDate(key: string): string {
  return shortDate.format(fromKey(key)).replace('.', '')
}

export function formatWeekdayShort(key: string): string {
  return weekdayShort.format(fromKey(key)).replace('.', '')
}

/** Beispiel: „8. – 14. Oktober" bzw. „28. Sept. – 4. Okt." bei Monatswechsel. */
export function formatWeekRange(startKey: string, endKey: string): string {
  const start = fromKey(startKey)
  const end = fromKey(endKey)
  if (start.getMonth() === end.getMonth()) {
    return `${start.getDate()}. – ${end.getDate()} ${monthOnly.format(end)}`
  }
  return `${formatShortDate(startKey)} – ${formatShortDate(endKey)}`
}

/** Farb- und Emoticon-Paletten des App. */

export interface HabitColor {
  id: string
  name: string
  /** Akzent im hellen Modus. */
  light: string
  /** Akzent im dunklen Modus (leicht aufgehellt, bleibt gedämpft). */
  dark: string
  /** Weiche Kartenfläche im hellen Modus. */
  softLight: string
}

export const HABIT_COLORS: HabitColor[] = [
  { id: 'clay', name: 'Terrakotta', light: '#a2491f', dark: '#dd8a5e', softLight: '#f7eae1' },
  { id: 'moss', name: 'Moos', light: '#4c6b33', dark: '#a3bc83', softLight: '#edf2e6' },
  { id: 'lake', name: 'See', light: '#31648e', dark: '#84aac9', softLight: '#e8f0f6' },
  { id: 'plum', name: 'Pflaume', light: '#7d4a66', dark: '#c68fa6', softLight: '#f3eaf0' },
  { id: 'gold', name: 'Ocker', light: '#8a6a1c', dark: '#d2b35c', softLight: '#f6efdc' },
  { id: 'slate', name: 'Schiefer', light: '#55565b', dark: '#a9a9a3', softLight: '#f0f0ee' },
]

export const HABIT_EMOJIS = [
  '💧',
  '🏃',
  '📖',
  '🧘',
  '✍️',
  '💪',
  '🦷',
  '😴',
  '🥗',
  '🚶',
  '🎨',
  '🪴',
]

export interface MoodLevel {
  value: number
  emoji: string
  label: string
}

export const MOOD_LEVELS: MoodLevel[] = [
  { value: 1, emoji: '😞', label: 'Schwer' },
  { value: 2, emoji: '😕', label: 'Durchwachsen' },
  { value: 3, emoji: '😐', label: 'Okay' },
  { value: 4, emoji: '🙂', label: 'Gut' },
  { value: 5, emoji: '😄', label: 'Hervorragend' },
]

export function moodByValue(value: number): MoodLevel {
  return MOOD_LEVELS[Math.min(4, Math.max(0, Math.round(value) - 1))]
}

/** Akzentfarbe einer Gewohnheit je nach aktuellem Modus. */
export function habitAccent(colorId: string, mode: 'light' | 'dark'): string {
  const c = HABIT_COLORS.find((c) => c.id === colorId) ?? HABIT_COLORS[0]
  return mode === 'dark' ? c.dark : c.light
}

/** Weiche Untergrundfläche einer Gewohnheitsfarbe (hellt via Farbmischung). */
export function habitSoftColor(colorId: string, mode: 'light' | 'dark'): string {
  const c = HABIT_COLORS.find((c) => c.id === colorId) ?? HABIT_COLORS[0]
  if (mode === 'dark') {
    return `color-mix(in srgb, ${c.dark} 16%, transparent)`
  }
  return c.softLight
}

/** Lesezeichen-Farbe auf einer gefüllten Akzentfläche (Weiß oder Tinte je nach Helligkeit). */
export function glyphOnAccent(accent: string): string {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(accent.slice(i, i + 2), 16))
  const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255
  return luminance > 0.55 ? '#111111' : '#ffffff'
}

import { addDays, todayKey } from './dates'

export interface Streaks {
  /** Aktive Serie: aufeinanderfolgende Tage, endend heute (oder gestern, falls heute noch offen). */
  current: number
  /** Längste je erreichte Serie. */
  longest: number
}

/**
 * Rechnet beide Serien aus einer Menge abgeschlossener Tage (YYYY-MM-DD) heraus.
 * Heute zählt nur, wenn bereits abgeschlossen; liegt heute noch offen, beginnt
 * die Zählung der aktiven Serie bei gestern – eine Serie „stirbt" nicht
 * automatisch am Morgen.
 */
export function computeStreaks(completedDates: Iterable<string>): Streaks {
  const set = new Set(completedDates)
  const today = todayKey()

  let current = 0
  let cursor = set.has(today) ? today : addDays(today, -1)
  while (set.has(cursor)) {
    current += 1
    cursor = addDays(cursor, -1)
  }

  let longest = 0
  let run = 0
  let previous: string | null = null
  for (const date of [...set].sort()) {
    run = previous !== null && addDays(previous, 1) === date ? run + 1 : 1
    if (run > longest) longest = run
    previous = date
  }

  return { current: Math.max(current, 0), longest: Math.max(longest, current) }
}

import { openDB, type IDBPDatabase } from 'idb'

/** Das gesamte Datenmodell lebt lokal in IndexedDB – kein Backend. */

export interface Habit {
  id: string
  name: string
  emoji: string
  /** Id aus HABIT_COLORS. */
  color: string
  createdAt: string
}

export interface Completion {
  /** `${habitId}::${date}` */
  id: string
  habitId: string
  /** YYYY-MM-DD */
  date: string
}

export interface MoodEntry {
  /** YYYY-MM-DD (eintrag pro Tag) */
  date: string
  /** 1–5 */
  value: number
  note: string
}

const DB_NAME = 'rhythm'
const DB_VERSION = 1

export function uid(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID()
  return `id-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export function completionId(habitId: string, date: string): string {
  return `${habitId}::${date}`
}

export type RhythmDB = IDBPDatabase<DBSchema>

interface DBSchema {
  habits: {
    key: string
    value: Habit
    indexes: { createdAt: string }
  }
  completions: {
    key: string
    value: Completion
    indexes: { habitId: string; date: string }
  }
  moods: {
    key: string
    value: MoodEntry
  }
}

let dbPromise: Promise<RhythmDB> | null = null

export function getDb(): Promise<RhythmDB> {
  if (!dbPromise) {
    dbPromise = openDB<RhythmDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        const habits = db.createObjectStore('habits', { keyPath: 'id' })
        habits.createIndex('createdAt', 'createdAt')
        const completions = db.createObjectStore('completions', { keyPath: 'id' })
        completions.createIndex('habitId', 'habitId')
        completions.createIndex('date', 'date')
        db.createObjectStore('moods', { keyPath: 'date' })
      },
    })
  }
  return dbPromise
}

export async function getAllHabits(): Promise<Habit[]> {
  const db = await getDb()
  return db.getAllFromIndex('habits', 'createdAt')
}

export async function putHabit(habit: Habit): Promise<void> {
  const db = await getDb()
  await db.put('habits', habit)
}

export async function deleteHabitWithCompletions(habitId: string): Promise<void> {
  const db = await getDb()
  const tx = db.transaction(['habits', 'completions'], 'readwrite')
  const completions = await tx.objectStore('completions').index('habitId').getAllKeys(habitId)
  for (const key of completions) await tx.objectStore('completions').delete(key)
  await tx.objectStore('habits').delete(habitId)
  await tx.done
}

export async function addCompletion(habitId: string, date: string): Promise<void> {
  const db = await getDb()
  await db.put('completions', { id: completionId(habitId, date), habitId, date })
}

export async function deleteCompletion(habitId: string, date: string): Promise<void> {
  const db = await getDb()
  await db.delete('completions', completionId(habitId, date))
}

export async function getAllCompletions(): Promise<Completion[]> {
  const db = await getDb()
  return db.getAll('completions')
}

export async function getAllMoods(): Promise<MoodEntry[]> {
  const db = await getDb()
  return db.getAll('moods')
}

export async function putMood(entry: MoodEntry): Promise<void> {
  const db = await getDb()
  await db.put('moods', entry)
}

export async function deleteMood(date: string): Promise<void> {
  const db = await getDb()
  await db.delete('moods', date)
}

export async function clearAllData(): Promise<void> {
  const db = await getDb()
  const tx = db.transaction(['habits', 'completions', 'moods'], 'readwrite')
  await Promise.all([
    tx.objectStore('habits').clear(),
    tx.objectStore('completions').clear(),
    tx.objectStore('moods').clear(),
  ])
  await tx.done
}

import { useCallback, useEffect, useState } from 'react'

export type ThemePreference = 'system' | 'light' | 'dark'
export type ThemeMode = 'light' | 'dark'

const STORAGE_KEY = 'rhythm-theme'
const QUERY = '(prefers-color-scheme: dark)'

function systemPrefersDark(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

function readStored(): ThemePreference {
  try {
    const v = localStorage.getItem(STORAGE_KEY)
    return v === 'light' || v === 'dark' ? v : 'system'
  } catch {
    return 'system'
  }
}

/**
 * Theme-Einstellung (System/Hell/Dunkel) mit Persistenz; die Lösung passiert
 * live, inkl. Reaktion auf Systemwechsel im „system"-Modus.
 */
export function useTheme() {
  const [preference, setPreference] = useState<ThemePreference>(readStored)
  const [mode, setMode] = useState<ThemeMode>(() =>
    readStored() === 'system' ? (systemPrefersDark() ? 'dark' : 'light') : readStored(),
  )

  useEffect(() => {
    const apply = () => {
      const resolved = preference === 'system' ? (systemPrefersDark() ? 'dark' : 'light') : preference
      document.documentElement.classList.toggle('dark', resolved === 'dark')
      setMode(resolved)
    }
    apply()
    if (preference !== 'system') return
    const mq = window.matchMedia(QUERY)
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [preference])

  const setTheme = useCallback((p: ThemePreference) => {
    setPreference(p)
    try {
      if (p === 'system') localStorage.removeItem(STORAGE_KEY)
      else localStorage.setItem(STORAGE_KEY, p)
    } catch {
      /* Speichern nicht möglich – Einstellung gilt nur für diese Sitzung */
    }
  }, [])

  return { preference, mode, setTheme }
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'
import * as db from './lib/db'
import { todayKey } from './lib/dates'

interface RhythmState {
  loaded: boolean
  habits: db.Habit[]
  completions: db.Completion[]
  moods: db.MoodEntry[]
}

export interface NewHabitInput {
  name: string
  emoji: string
  color: string
}

interface RhythmStore extends RhythmState {
  addHabit: (input: NewHabitInput) => Promise<void>
  updateHabit: (id: string, patch: Partial<Omit<db.Habit, 'id' | 'createdAt'>>) => Promise<void>
  deleteHabit: (id: string) => Promise<void>
  toggleCompletion: (habitId: string, date?: string) => Promise<void>
  setMood: (date: string, value: number, note: string) => Promise<void>
  clearAll: () => Promise<void>
}

const RhythmContext = createContext<RhythmStore | null>(null)

export function RhythmProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<RhythmState>({
    loaded: false,
    habits: [],
    completions: [],
    moods: [],
  })

  const reload = useCallback(async () => {
    try {
      const [habits, completions, moods] = await Promise.all([
        db.getAllHabits(),
        db.getAllCompletions(),
        db.getAllMoods(),
      ])
      setState({ loaded: true, habits, completions, moods })
    } catch (error) {
      console.error('Rhythm: Laden der Daten fehlgeschlagen', error)
      setState((s) => ({ ...s, loaded: true }))
    }
  }, [])

  useEffect(() => {
    void reload()
  }, [reload])

  // Änderungen in anderen Fenstern/Taben spiegeln (gleiche Ursprungsdaten).
  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (event.key === null || event.key.startsWith('rhythm')) void reload()
    }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [reload])

  const addHabit = useCallback(
    async (input: NewHabitInput) => {
      const habit: db.Habit = {
        id: db.uid(),
        name: input.name.trim(),
        emoji: input.emoji,
        color: input.color,
        createdAt: new Date().toISOString(),
      }
      if (!habit.name) return
      setState((s) => ({ ...s, habits: [...s.habits, habit] }))
      try {
        await db.putHabit(habit)
      } catch (error) {
        console.error('Rhythm: Habit konnte nicht gespeichert werden', error)
        await reload()
      }
    },
    [reload],
  )

  const updateHabit = useCallback(
    async (id: string, patch: Partial<Omit<db.Habit, 'id' | 'createdAt'>>) => {
      setState((s) => ({
        ...s,
        habits: s.habits.map((h) => (h.id === id ? { ...h, ...patch } : h)),
      }))
      try {
        const current = await db.getAllHabits()
        const habit = current.find((h) => h.id === id)
        if (habit) await db.putHabit({ ...habit, ...patch, name: patch.name ?? habit.name })
      } catch (error) {
        console.error('Rhythm: Änderung konnte nicht gespeichert werden', error)
        await reload()
      }
    },
    [reload],
  )

  const deleteHabit = useCallback(
    async (id: string) => {
      setState((s) => ({
        ...s,
        habits: s.habits.filter((h) => h.id !== id),
        completions: s.completions.filter((c) => c.habitId !== id),
      }))
      try {
        await db.deleteHabitWithCompletions(id)
      } catch (error) {
        console.error('Rhythm: Löschen fehlgeschlagen', error)
        await reload()
      }
    },
    [reload],
  )

  const toggleCompletion = useCallback(
    async (habitId: string, date = todayKey()) => {
      const id = db.completionId(habitId, date)
      const exists = state.completions.some((c) => c.id === id)
      setState((s) => ({
        ...s,
        completions: exists
          ? s.completions.filter((c) => c.id !== id)
          : [...s.completions, { id, habitId, date }],
      }))
      try {
        if (exists) await db.deleteCompletion(habitId, date)
        else await db.addCompletion(habitId, date)
      } catch (error) {
        console.error('Rhythm: Abhaken fehlgeschlagen', error)
        await reload()
      }
    },
    [state.completions, reload],
  )

  const setMood = useCallback(
    async (date: string, value: number, note: string) => {
      setState((s) => ({
        ...s,
        moods: [...s.moods.filter((m) => m.date !== date), { date, value, note }],
      }))
      try {
        await db.putMood({ date, value, note })
      } catch (error) {
        console.error('Rhythm: Stimmung konnte nicht gespeichert werden', error)
        await reload()
      }
    },
    [reload],
  )

  const clearAll = useCallback(async () => {
    setState({ loaded: true, habits: [], completions: [], moods: [] })
    try {
      await db.clearAllData()
    } catch (error) {
      console.error('Rhythm: Leeren der Daten fehlgeschlagen', error)
      await reload()
    }
  }, [reload])

  const value = useMemo<RhythmStore>(
    () => ({ ...state, addHabit, updateHabit, deleteHabit, toggleCompletion, setMood, clearAll }),
    [state, addHabit, updateHabit, deleteHabit, toggleCompletion, setMood, clearAll],
  )

  return <RhythmContext.Provider value={value}>{children}</RhythmContext.Provider>
}

export function useRhythm(): RhythmStore {
  const ctx = useContext(RhythmContext)
  if (!ctx) throw new Error('useRhythm muss innerhalb von <RhythmProvider> verwendet werden')
  return ctx
}

