import { CalendarCheck, ChartLineUp, Gear } from '@phosphor-icons/react'

export type TabId = 'heute' | 'woche' | 'einstellungen'

const TABS = [
  { id: 'heute' as const, label: 'Heute', Icon: CalendarCheck },
  { id: 'woche' as const, label: 'Woche', Icon: ChartLineUp },
  { id: 'einstellungen' as const, label: 'Einstellungen', Icon: Gear },
]

interface BottomNavProps {
  tab: TabId
  onChange: (tab: TabId) => void
}

/** Bottom-Navigation mit 3 Tabs – mindestens 44 px Touch-Ziel. */
export function BottomNav({ tab, onChange }: BottomNavProps) {
  return (
    <nav className="fixed inset-x-0 bottom-0 z-40" aria-label="Hauptnavigation">
      <div className="mx-auto max-w-md px-5">
        <div
          className="flex items-stretch justify-around border-t border-line bg-surface/95 backdrop-blur-sm"
          style={{ paddingBottom: 'calc(0.5rem + env(safe-area-inset-bottom))' }}
        >
          {TABS.map(({ id, label, Icon }) => {
            const active = tab === id
            return (
              <button
                key={id}
                type="button"
                onClick={() => onChange(id)}
                aria-current={active ? 'page' : undefined}
                className={
                  'flex min-h-14 min-w-11 flex-col items-center justify-center gap-1 rounded-lg px-3 py-2 transition-colors duration-200 ' +
                  (active ? 'text-ink' : 'text-faint hover:text-muted')
                }
              >
                <Icon size={20} weight={active ? 'fill' : 'regular'} />
                <span className="text-[11px] font-medium tracking-[0.02em]">{label}</span>
              </button>
            )
          })}
        </div>
      </div>
    </nav>
  )
}

import type { CSSProperties } from 'react'
import { Check } from '@phosphor-icons/react'
import type { Habit } from '../lib/db'
import { habitAccent, glyphOnAccent, habitSoftColor } from '../lib/palette'
import type { Streaks } from '../lib/streaks'

interface HabitRowProps {
  habit: Habit
  index: number
  done: boolean
  streaks: Streaks
  mode: 'light' | 'dark'
  onToggle: () => void
  onEdit: () => void
}

function dayWord(count: number): string {
  return count === 1 ? 'Tag' : 'Tage'
}

function streakText(streaks: Streaks): string {
  const { current, longest } = streaks
  if (current > 0 && longest > current) return `Serie ${current} ${dayWord(current)} · Rekord ${longest}`
  if (current > 0) return `Serie ${current} ${dayWord(current)}`
  if (longest > 0) return `Rekord ${longest} ${dayWord(longest)}`
  return 'Noch keine Serie'
}

export function HabitRow({ habit, index, done, streaks, mode, onToggle, onEdit }: HabitRowProps) {
  const accent = habitAccent(habit.color, mode)
  const soft = habitSoftColor(habit.color, mode)
  const glyph = glyphOnAccent(accent)

  return (
    <li className="rise" style={{ '--index': index } as CSSProperties}>
      <div
        className={
          'flex items-center gap-3 rounded-card border bg-surface px-4 py-3.5 shadow-soft transition-[background-color,border-color] duration-300 ' +
          (done ? '' : 'border-line')
        }
        style={done ? { borderColor: accent, backgroundColor: soft } : undefined}
      >
        <span
          className="grid h-10 w-10 shrink-0 place-items-center rounded-[10px] border border-line bg-canvas text-[22px]"
          aria-hidden="true"
        >
          {habit.emoji}
        </span>

        <button
          type="button"
          onClick={onEdit}
          aria-label={`Gewohnheit „${habit.name}“ bearbeiten`}
          className="min-h-11 min-w-0 flex-1 rounded-lg text-left"
        >
          <span
            className={
              'block truncate text-[15px] font-medium transition-opacity duration-300 ' +
              (done ? 'text-muted' : 'text-ink')
            }
          >
            {habit.name}
          </span>
          <span className="mt-0.5 block truncate font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">
            {streakText(streaks)}
          </span>
        </button>

        <button
          type="button"
          onClick={onToggle}
          aria-pressed={done}
          aria-label={done ? `„${habit.name}“ aufheben` : `„${habit.name}“ abhaken`}
          className={
            'grid h-12 w-12 shrink-0 place-items-center rounded-full border-2 transition-[background-color,border-color] duration-200 active:scale-95 ' +
            (done ? 'border-transparent' : 'border-line-strong hover:border-ink/60')
          }
          style={done ? { backgroundColor: accent } : undefined}
        >
          {done ? (
            <span className="pop" style={{ color: glyph }}>
              <Check size={22} weight="bold" />
            </span>
          ) : (
            <span className="text-faint" aria-hidden="true">
              <Check size={22} weight="bold" style={{ opacity: 0.25 }} />
            </span>
          )}
        </button>
      </div>
    </li>
  )
}

import { useEffect, useRef, useState } from 'react'
import { X } from '@phosphor-icons/react'
import type { Habit } from '../lib/db'
import { HABIT_COLORS, HABIT_EMOJIS, habitAccent } from '../lib/palette'
import { useRhythm } from '../store'
import { useTheme } from '../lib/theme'

interface HabitFormProps {
  /** null = neues Habit anlegen */
  habit: Habit | null
  onClose: () => void
}

/** Bottom-Sheet zum Anlegen und Bearbeiten von Gewohnheiten. */
export function HabitForm({ habit, onClose }: HabitFormProps) {
  const { mode } = useTheme()
  const { addHabit, updateHabit, deleteHabit } = useRhythm()

  const [name, setName] = useState(habit?.name ?? '')
  const [emoji, setEmoji] = useState(habit?.emoji ?? HABIT_EMOJIS[0])
  const [color, setColor] = useState(habit?.color ?? HABIT_COLORS[0].id)
  const [confirmDelete, setConfirmDelete] = useState(false)
  const [busy, setBusy] = useState(false)

  const nameRef = useRef<HTMLInputElement>(null)
  const firstSwatchRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    nameRef.current?.focus()
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  async function save() {
    const trimmed = name.trim()
    if (!trimmed || busy) return
    setBusy(true)
    if (habit) {
      await updateHabit(habit.id, { name: trimmed, emoji, color })
    } else {
      await addHabit({ name: trimmed, emoji, color })
    }
    onClose()
  }

  async function remove() {
    if (!habit || busy) return
    if (!confirmDelete) {
      setConfirmDelete(true)
      return
    }
    setBusy(true)
    await deleteHabit(habit.id)
    onClose()
  }

  const selectedAccent = habitAccent(color, mode)

  return (
    <div className="fixed inset-0 z-50">
      <button
        type="button"
        aria-label="Schließen"
        onClick={onClose}
        className="fade-in absolute inset-0 h-full w-full cursor-default bg-ink/25 backdrop-blur-[2px]"
        style={{ backgroundColor: mode === 'dark' ? 'rgba(0,0,0,0.55)' : undefined }}
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-label={habit ? 'Gewohnheit bearbeiten' : 'Neue Gewohnheit'}
        className="sheet-up absolute inset-x-0 bottom-0 mx-auto max-w-md"
      >
        <div
          className="rounded-t-card border border-b-0 border-line bg-surface shadow-soft"
          style={{ paddingBottom: 'calc(1.25rem + env(safe-area-inset-bottom))' }}
        >
          <div className="mx-auto mb-4 mt-3 h-1 w-10 rounded-full bg-line-strong" aria-hidden="true" />

          <div className="flex items-center justify-between px-5">
            <h2 className="font-serif text-[22px] font-semibold tracking-[-0.02em] text-ink">
              {habit ? 'Gewohnheit bearbeiten' : 'Neue Gewohnheit'}
            </h2>
            <button
              type="button"
              onClick={onClose}
              aria-label="Schließen"
              className="grid h-9 w-9 place-items-center rounded-full border border-line text-muted hover:text-ink"
            >
              <X size={14} weight="bold" />
            </button>
          </div>

          <div className="mt-5 space-y-6 px-5">
            <div>
              <label htmlFor="habit-name" className="text-xs font-medium tracking-[0.05em] text-muted uppercase">
                Name
              </label>
              <input
                id="habit-name"
                ref={nameRef}
                value={name}
                onChange={(e) => setName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') void save()
                }}
                placeholder="z. B. Morgens 500 ml Wasser trinken"
                autoComplete="off"
                className="mt-2 h-11 w-full rounded-[10px] border border-line bg-canvas px-3.5 text-[15px] text-ink outline-none placeholder:text-faint focus-visible:border-ink/50"
              />
            </div>

            <div>
              <span className="text-xs font-medium tracking-[0.05em] text-muted uppercase">Symbol</span>
              <div className="mt-2 grid grid-cols-6 gap-2" role="group" aria-label="Symbol wählen">
                {HABIT_EMOJIS.map((e) => {
                  const selected = e === emoji
                  return (
                    <button
                      key={e}
                      type="button"
                      ref={selected ? firstSwatchRef : undefined}
                      aria-pressed={selected}
                      aria-label={`Symbol ${e}`}
                      onClick={() => setEmoji(e)}
                      className={
                        'grid h-11 place-items-center rounded-[10px] border text-[20px] transition-transform active:scale-95 ' +
                        (selected ? 'border-ink bg-canvas' : 'border-line hover:border-line-strong')
                      }
                    >
                      {e}
                    </button>
                  )
                })}
              </div>
            </div>

            <div>
              <span className="text-xs font-medium tracking-[0.05em] text-muted uppercase">Farbe</span>
              <div className="mt-2.5 flex gap-3" role="group" aria-label="Farbe wählen">
                {HABIT_COLORS.map((c) => {
                  const selected = c.id === color
                  const accent = habitAccent(c.id, mode)
                  return (
                    <button
                      key={c.id}
                      type="button"
                      title={c.name}
                      aria-pressed={selected}
                      aria-label={`Farbe ${c.name}`}
                      onClick={() => setColor(c.id)}
                      className={
                        'h-9 w-9 rounded-full transition-transform active:scale-95 ' +
                        (selected
                          ? 'ring-2 ring-ink ring-offset-2 ring-offset-surface'
                          : 'ring-1 ring-line')
                      }
                      style={{ backgroundColor: accent }}
                    />
                  )
                })}
              </div>
              <p className="mt-2 text-xs text-faint">{HABIT_COLORS.find((c) => c.id === color)?.name}</p>
            </div>

            <div className="flex gap-3 pt-1">
              {habit ? (
                <button
                  type="button"
                  onClick={() => void remove()}
                  className="min-h-11 rounded-[6px] px-4 text-sm font-medium text-danger transition-colors hover:bg-danger-soft"
                >
                  {confirmDelete ? 'Wirklich löschen?' : 'Löschen'}
                </button>
              ) : null}
              <button
                type="button"
                onClick={() => void save()}
                disabled={!name.trim() || busy}
                className="min-h-11 flex-1 rounded-[6px] bg-ink font-medium text-canvas transition-[transform,opacity] active:scale-[0.98] disabled:opacity-40"
              >
                {habit ? 'Speichern' : 'Hinzufügen'}
              </button>
              <button
                type="button"
                onClick={onClose}
                className="min-h-11 rounded-[6px] border border-line px-4 text-sm font-medium text-muted"
              >
                Abbrechen
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

