          </div>

          <dl className="mt-5 flex justify-between gap-3 border-t border-line pt-4">
            <div>
              <dt className="font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">
                Erledigt
              </dt>
              <dd className="mt-1 text-[15px] font-medium text-ink">
                {weekDone} von {habits.length * 7}
              </dd>
            </div>
            <div className="text-right">
              <dt className="font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">
                Ø Stimmung
              </dt>
              <dd className="mt-1 text-[15px] font-medium text-ink">
                {avgMood === null ? '–' : avgMood.toFixed(1).replace('.', ',')}
              </dd>
            </div>
            <div className="text-right">
              <dt className="font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">
                Beste Serie
              </dt>
              <dd className="mt-1 text-[15px] font-medium text-ink">
                {bestStreak === 0 ? '–' : `${bestStreak} Tage`}
              </dd>
            </div>
          </dl>
        </section>
      ) : (
        <EmptyState
          index={1}
          title="Diese Woche ist noch leer"
          text="Heutiges Abhaken und deine Stimmung erscheinen ab morgen hier im Chart."
        />
      )}
    </div>
  )
}

/** Längste aufeinanderfolgende Abhake-Tage über alle Habits zusammen (letzte 7 Tage). */
function computeWeekBestStreak(completions: { date: string }[]): number {
  const dates = new Set(completions.map((c) => c.date))
  let best = 0
  let run = 0
  let previous: string | null = null
  for (const date of [...dates].sort()) {
    run = previous !== null && isNextDay(previous, date) ? run + 1 : 1
    if (run > best) best = run
    previous = date
  }
  return best
}

function isNextDay(a: string, b: string): boolean {
  const [ay, am, ad] = a.split('-').map(Number)
  const [by, bm, bd] = b.split('-').map(Number)
  const da = new Date(ay, am - 1, ad)
  const db = new Date(by, bm - 1, bd)
  da.setDate(da.getDate() + 1)
  return da.getTime() === db.getTime()
}

